      sceneId,
      text,
      startTime: currentChunk[0].start,
      endTime: currentChunk[currentChunk.length - 1].end,
      emphasisType,
      highlightWords,
      presetType,
      style: { fontPreset, boxHighlight, skew, baseColor }
